import{_ as t,o as r,c as o,a2 as a}from"./chunks/framework.CyZTVJbV.js";const p=JSON.parse('{"title":"WebAuthn Passkey Dogfood — userVerification 4 pattern quality report","description":"","frontmatter":{},"headers":[],"relativePath":"quality-reports/auth/webauthn-passkey-app-user-verification.md","filePath":"quality-reports/auth/webauthn-passkey-app-user-verification.md"}'),i={name:"quality-reports/auth/webauthn-passkey-app-user-verification.md"};function d(s,e,c,n,u,l){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="webauthn-passkey-dogfood-—-userverification-4-pattern-quality-report" tabindex="-1">WebAuthn Passkey Dogfood — userVerification 4 pattern quality report <a class="header-anchor" href="#webauthn-passkey-dogfood-—-userverification-4-pattern-quality-report" aria-label="Permalink to &quot;WebAuthn Passkey Dogfood — userVerification 4 pattern quality report&quot;">​</a></h1><p>Sub-Issue #858 (v1.21-2c) fidelity report for the userVerification axis of the dogfood app (<code>examples/dogfood-webauthn-passkey-app</code>). Covers the four patterns the RP accepts on both <code>/register</code> and <code>/signin</code> and asserts the UV bit (WebAuthn L3 §6.1 authenticatorData flags) matches caller intent across mock and real drivers.</p><h2 id="userverification-vocabulary" tabindex="-1">userVerification vocabulary <a class="header-anchor" href="#userverification-vocabulary" aria-label="Permalink to &quot;userVerification vocabulary&quot;">​</a></h2><p>Three spec values from WebAuthn L3 §5.4.6 plus one kiwa-only sentinel used by the dogfood app to probe the &quot;RP asked for a spec-invalid value&quot; path.</p><table tabindex="0"><thead><tr><th>value</th><th>source</th><th>behaviour</th></tr></thead><tbody><tr><td><code>required</code></td><td>WebAuthn L3 §5.4.6</td><td>Authenticator MUST perform user verification (biometric / PIN). Fails when authenticator cannot satisfy UV.</td></tr><tr><td><code>preferred</code></td><td>WebAuthn L3 §5.4.6 (default)</td><td>Authenticator SHOULD perform UV; RP accepts fallback when the authenticator lacks UV.</td></tr><tr><td><code>discouraged</code></td><td>WebAuthn L3 §5.4.6</td><td>Authenticator MUST NOT perform UV even when capable — UV bit stays 0.</td></tr><tr><td><code>impossible</code></td><td>kiwa dogfood sentinel</td><td>Not a WebAuthn value; RP rejects with <code>invalid_user_verification</code> (400) before dispatching. Real SimpleWebAuthn deployments reject the same value at the schema layer.</td></tr></tbody></table><h2 id="fidelity-axes-userverification" tabindex="-1">Fidelity axes (userVerification) <a class="header-anchor" href="#fidelity-axes-userverification" aria-label="Permalink to &quot;Fidelity axes (userVerification)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>axis</th><th>mock (<code>@kiwa-lab/auth</code>)</th><th>real (SimpleWebAuthn + Chrome Virtual Authenticator)</th><th>assertion</th></tr></thead><tbody><tr><td>1. <code>required</code> on UV-capable authenticator</td><td>Succeeds; assertion UV bit = 1</td><td>Succeeds; assertion UV bit = 1</td><td>Both drivers set UV=1 in <code>authenticatorData</code> byte 32 (<code>FLAG_USER_VERIFIED = 0x04</code>).</td></tr><tr><td>2. <code>required</code> on non-UV authenticator</td><td>Throws <code>userVerification=required but authenticator does not support user verification</code>; trace <code>errorKind = user_verification_unsupported</code></td><td>SimpleWebAuthn <code>verifyAuthenticationResponse</code> throws <code>UserVerificationRequirement not satisfied</code>; 400</td><td>Both surface the failure as a client-visible 400 with a stable error kind.</td></tr><tr><td>3. <code>preferred</code> on UV-capable authenticator</td><td>UV bit = 1</td><td>UV bit = 1</td><td>Baseline &quot;everything worked&quot; path.</td></tr><tr><td>4. <code>preferred</code> on non-UV authenticator</td><td>Succeeds; UV bit = 0</td><td>Succeeds; UV bit = 0</td><td>Fallback path — assertion still verifies but RP knows UV was not performed.</td></tr><tr><td>5. <code>discouraged</code> on any authenticator</td><td>UV bit = 0 (mock respects §5.4.6 even on a UV-capable authenticator, per <code>webauthn/assertion.ts</code> v1.21-2c)</td><td>UV bit = 0</td><td>The mock previously always set UV bit off <code>hasUserVerification</code>; #858 flipped this so <code>discouraged</code> clears the bit.</td></tr><tr><td>6. <code>impossible</code> request</td><td>RP throws <code>userVerification=impossible is not a WebAuthn L3 §5.4.6 value</code>; trace <code>errorKind = user_verification_impossible</code>; route returns 400</td><td>RP schema layer rejects with 400 before dispatch</td><td>Both drivers refuse before invoking the authenticator.</td></tr></tbody></table><h2 id="test-coverage" tabindex="-1">Test coverage <a class="header-anchor" href="#test-coverage" aria-label="Permalink to &quot;Test coverage&quot;">​</a></h2><ul><li><code>tests/user-verification.spec.ts</code> — 18 tests across 4 describe blocks: <ul><li><code>userVerification 4 pattern — register ceremony</code> — 5 tests covering each of the four patterns (<code>required</code> × 2 authenticator shapes, <code>preferred</code>, <code>discouraged</code>, <code>impossible</code>) on the register side</li><li><code>userVerification 4 pattern — signin ceremony</code> — 6 tests covering the same four patterns on the signin side plus the UV bit table</li><li><code>userVerification — POST /register + POST /signin route validation</code> — 6 tests exercising <code>?uv=</code> query param wins over body, <code>impossible</code> returns 400 <code>register_failed</code> / <code>signin_failed</code>, garbage values return 400 <code>invalid_user_verification</code>, <code>parseUserVerification</code> narrows the vocabulary</li><li><code>fidelity axis — UV bit matches caller intent (AC #3)</code> — 1 parameterised test that asserts the required / preferred / discouraged patterns produce the expected UV bit table on a UV-capable authenticator</li></ul></li></ul><h2 id="route-handler-surface-sub-issue-858" tabindex="-1">Route-handler surface (Sub-Issue #858) <a class="header-anchor" href="#route-handler-surface-sub-issue-858" aria-label="Permalink to &quot;Route-handler surface (Sub-Issue #858)&quot;">​</a></h2><p>Both <code>/register</code> and <code>/signin</code> accept userVerification through two channels:</p><ul><li>Body — <code>authenticatorSelection.userVerification</code> (register) / <code>userVerification</code> (signin)</li><li>Query — <code>?uv=required|preferred|discouraged|impossible</code></li></ul><p>Query wins when both are set. Any value outside the four dogfood patterns returns 400 <code>invalid_user_verification</code> with a message listing the accepted values. This lets a browser-side toggle flip UV without re-encoding the whole POST body while still gate-keeping the RP against typos.</p><h2 id="http-status-mapping" tabindex="-1">HTTP status mapping <a class="header-anchor" href="#http-status-mapping" aria-label="Permalink to &quot;HTTP status mapping&quot;">​</a></h2><table tabindex="0"><thead><tr><th>userVerification outcome</th><th>HTTP status</th><th>error field</th></tr></thead><tbody><tr><td>Ceremony succeeds</td><td>200</td><td>(n/a)</td></tr><tr><td><code>required</code> on non-UV authenticator</td><td>400</td><td><code>register_failed</code> / <code>signin_failed</code></td></tr><tr><td><code>impossible</code> requested</td><td>400</td><td><code>register_failed</code> / <code>signin_failed</code></td></tr><tr><td>Value outside the four patterns</td><td>400</td><td><code>invalid_user_verification</code></td></tr><tr><td>RP env missing (real driver)</td><td>500</td><td><code>register_failed</code> / <code>signin_failed</code></td></tr></tbody></table><h2 id="known-follow-ups" tabindex="-1">Known follow-ups <a class="header-anchor" href="#known-follow-ups" aria-label="Permalink to &quot;Known follow-ups&quot;">​</a></h2><ul><li>Sub-Issue #859 — residentKey + <code>/manage</code> layers on top of this axis; the release gate consumes both this report and the register-attestation report to produce the final v1.21-2 fidelity number.</li><li>Real driver — <code>KIWA_WEBAUTHN_REAL_READY=1</code> gate is still unwired; Chrome Virtual Authenticator will be exercised through the real driver once the Playwright wiring in Sub-Issue #859 lands. Until then the <code>real</code> column above is a spec-based assertion, not an executed diff.</li></ul>',17)])])}const f=t(i,[["render",d]]);export{p as __pageData,f as default};
